// Every page is static HTML (the doc pages are generated by rebuild-docs.mjs). This script only
// adds the interactive bits: copy buttons, the mobile docs menu, search, and the Discord dialog.
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

// ---------- Old links ----------

// The docs used to live at #/docs/<page>#<anchor> on the home page; send those to the page.
{
  const match = location.hash.match(/^#\/docs\/([^#]+)(?:#(.*))?$/);
  if (match && !$(".page-links")) {
    const file = match[1] === "README" ? "index.html" : match[1] + ".html";
    location.replace("docs/" + file + (match[2] ? "#" + match[2] : ""));
  }
}

// ---------- Docs ----------

// Copy buttons on code blocks.
$$(".doc-content pre").forEach((pre) => {
  const button = document.createElement("button");
  button.className = "copy-code";
  button.textContent = "Copy";
  button.setAttribute("aria-label", "Copy code");
  button.onclick = () => copyCode(pre.querySelector("code"), button);
  pre.append(button);
});

async function copyCode(code, button) {
  try {
    await navigator.clipboard.writeText(code.textContent);
    button.textContent = "Copied";
    setTimeout(() => (button.textContent = "Copy"), 1500);
  } catch {
    button.textContent = "Select to copy";
    const range = document.createRange();
    range.selectNodeContents(code);
    getSelection().removeAllRanges();
    getSelection().addRange(range);
  }
}

const sidebar = $(".docs-sidebar");
const mobileToggle = $(".docs-mobile");
if (mobileToggle) {
  mobileToggle.onclick = () => {
    const open = sidebar.classList.toggle("open");
    mobileToggle.setAttribute("aria-expanded", open);
  };
}

// Search: the page list comes from the sidebar; the Markdown of every page (docs-data.js) is
// loaded the first time someone uses the search box.
const search = $("#docs-search");
if (search) {
  const pageLinks = $(".page-links");
  const results = $(".search-results");
  const pages = $$("a", pageLinks).map((a) => ({
    file: a.getAttribute("href"),
    id: a.getAttribute("href") === "index.html" ? "README" : a.getAttribute("href").replace(/\.html$/, ""),
    title: a.textContent.trim(),
  }));

  let loading;
  const loadIndex = () =>
    (loading ??= new Promise((resolve, reject) => {
      if (window.BOZ_DOCS) return resolve();
      const script = document.createElement("script");
      script.src = search.dataset.index;
      script.onload = resolve;
      script.onerror = reject;
      document.head.append(script);
    }));

  search.addEventListener("focus", () => loadIndex().catch(() => {}), { once: true });

  search.oninput = async () => {
    const q = search.value.trim().toLowerCase();
    pageLinks.hidden = !!q;
    if (!q) return results.replaceChildren();
    try {
      await loadIndex();
    } catch {
      loading = undefined;
      results.replaceChildren(Object.assign(document.createElement("p"), { textContent: "Search could not load. Try again." }));
      return;
    }
    if (search.value.trim().toLowerCase() !== q) return; // a newer search is running
    results.replaceChildren();
    const matches = pages.filter((p) =>
      (p.title + " " + window.BOZ_DOCS[p.id]).toLowerCase().includes(q),
    );
    if (!matches.length) {
      const p = document.createElement("p");
      p.textContent = "No results. Try “weapons” or “Lua”.";
      results.append(p);
      return;
    }
    for (const page of matches) {
      const raw = window.BOZ_DOCS[page.id].replace(/[#*`|]/g, " ");
      const start = Math.max(0, raw.toLowerCase().indexOf(q) - 35);
      const a = document.createElement("a");
      const small = document.createElement("small");
      a.href = page.file;
      a.textContent = page.title;
      small.textContent = raw.slice(start, start + 120) + "…";
      a.append(small);
      results.append(a);
    }
  };
}

// ---------- Discord dialog ----------

const dialog = $("#discord-dialog");
document.addEventListener("click", (e) => {
  if (!e.target.closest("[data-discord]")) return;
  e.preventDefault();
  const url = window.BOZ_CONFIG?.discordUrl;
  if (url && /^https:\/\/(discord\.gg\/|discord\.com\/invite\/)/.test(url)) {
    window.open(url, "_blank", "noopener");
  } else dialog.showModal();
});
$(".dialog-close").onclick = () => dialog.close();
dialog.onclick = (e) => {
  if (e.target === dialog) dialog.close();
};
